<?php $edit=!empty($_GET['edit'])?must('customers',(int)$_GET['edit']):[];if(($_POST['action']??'')==='customer'&&isset($error))$edit=$_POST; ?>
<div class="columns"><section class="card"><h2><?=$edit?'Edit':'New'?> customer</h2><?php startform('customer',['id'=>$edit['id']??'']);field('Customer / company','name',$edit['name']??'','text',true,'maxlength="160"');field('Email','email',$edit['email']??'','email',false,'maxlength="160"');field('Phone / WhatsApp','phone',$edit['phone']??'');field('Country','country',$edit['country']??'');area('Address','address',$edit['address']??''); ?><button>Save customer</button></form></section>
<section class="card"><h2>Customer directory</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Country</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM customers ORDER BY name') as $c): ?><tr><td><a href="index.php?page=customers&edit=<?=$c['id']?>"><?=e($c['name'])?></a></td><td><?=e($c['email'])?><small><?=e($c['phone'])?></small></td><td><?=e($c['country'])?></td></tr><?php endforeach ?></tbody></table></div></section></div>
